<?php
declare(strict_types=1);
require __DIR__.'/auth.php'; require_admin(); require __DIR__.'/db.php'; header('Content-Type: application/json; charset=utf-8');
$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){ $r=mysqli_query($conn,'SELECT event_id,event_name,description,event_date,poster FROM events ORDER BY event_date ASC,event_id DESC'); $rows=[]; while($r&&$x=$r->fetch_assoc())$rows[]=$x; echo json_encode(['success'=>true,'data'=>$rows]); exit; }
$body=$method==='POST' ? $_POST : (json_decode(file_get_contents('php://input'),true)??[]); $id=(int)($body['event_id']??0); $name=trim((string)($body['event_name']??'')); $date=(string)($body['event_date']??''); $desc=trim((string)($body['description']??'')); if(in_array($method,['POST','PUT'],true)&&($name===''||$date==='')){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Event name and date are required.']);exit;}
if($method==='POST'){
 $poster=null;
 if(isset($_FILES['poster']) && $_FILES['poster']['error']!==UPLOAD_ERR_NO_FILE){$file=$_FILES['poster'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if($file['error']!==UPLOAD_ERR_OK){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Poster upload failed.']);exit;}if($file['size']>2*1024*1024){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Poster must be 2 MB or smaller.']);exit;}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($allowed[$mime])){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Invalid file type. Upload JPG, PNG, or WebP only.']);exit;}$poster=bin2hex(random_bytes(10)).'.'.$allowed[$mime];if(!is_dir(__DIR__.'/uploads/posters'))mkdir(__DIR__.'/uploads/posters',0775,true);if(!move_uploaded_file($file['tmp_name'],__DIR__.'/uploads/posters/'.$poster)){$poster=null;}}
 else {http_response_code(422);echo json_encode(['success'=>false,'message'=>'Please upload a poster.']);exit;}
 $q=mysqli_prepare($conn,'INSERT INTO events(event_name,description,event_date,poster) VALUES(?,?,?,?)');mysqli_stmt_bind_param($q,'ssss',$name,$desc,$date,$poster);$ok=mysqli_stmt_execute($q);$new=mysqli_insert_id($conn);mysqli_stmt_close($q);log_action($conn,'event_create',$name);echo json_encode(['success'=>$ok,'event_id'=>$new,'message'=>$ok?'Event created successfully.':'Event could not be created.']);exit; }
if($method==='PUT'){ $q=mysqli_prepare($conn,'UPDATE events SET event_name=?,description=?,event_date=? WHERE event_id=?');mysqli_stmt_bind_param($q,'sssi',$name,$desc,$date,$id);$ok=mysqli_stmt_execute($q);mysqli_stmt_close($q);log_action($conn,'event_update',(string)$id);echo json_encode(['success'=>$ok,'message'=>$ok?'Event updated successfully.':'Event could not be updated.']);exit; }
if($method==='DELETE'){ $old=mysqli_prepare($conn,'SELECT poster FROM events WHERE event_id=?');mysqli_stmt_bind_param($old,'i',$id);mysqli_stmt_execute($old);$row=mysqli_stmt_get_result($old)->fetch_assoc();mysqli_stmt_close($old);$q=mysqli_prepare($conn,'DELETE FROM events WHERE event_id=?');mysqli_stmt_bind_param($q,'i',$id);$ok=mysqli_stmt_execute($q);mysqli_stmt_close($q);if($ok&&$row&&$row['poster']){@unlink(__DIR__.'/uploads/posters/'.$row['poster']);}log_action($conn,'event_delete',(string)$id);echo json_encode(['success'=>$ok,'message'=>$ok?'Event deleted successfully.':'Event could not be deleted.']);exit; }
http_response_code(405);echo json_encode(['success'=>false,'message'=>'Method not allowed.']);

